var DATA = {"mode": "dia", "dia": 2.5, "common": [2, 2.5, 3]};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="dia"){
  show("Hole saw",DATA.dia+" in");
  show("Grommet","sized for "+DATA.dia+" in holes");
  show("Common",DATA.common.join(", "));
}else if(m==="pick"){
  show("Cables",DATA.n+" cables ~"+DATA.mm+" mm dia");
  show("Pick",DATA.pick);
  show("Rule","brush insert for mixed bundles");
}else if(m==="fill"){
  var area=Math.PI*Math.pow(DATA.dia*25.4/2,2);
  var fill=Math.round(DATA.cable/area*100);
  show("Hole area",Math.round(area)+" sq mm");
  show("Cable area",Math.round(DATA.cable)+" sq mm");
  show("Fill",fill+"%");
  show("Rule",fill<=60?"OK - under 60%":"TOO FULL - go up a size");
}else if(m==="brush"){
  show("Brush insert","cables pass, dust stays out");
  show("Best for","mixed bundles that change often");
}else if(m==="install"){
  console.log("Install:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}else if(m==="metal"){
  show("Metal","premium look, crisp edge");
  show("Plastic","standard, many finishes");
}else if(m==="desk"){
  show("Desk thickness",DATA.t+" in");
  show("Standard grommets","fit tops to ~1.5 in");
}else if(m==="plan"){
  show("Positions",DATA.where);
  show("Count",DATA.n+" grommets");
  show("Rule","one behind the monitor, one by the PC");
}else if(m==="count"){
  show("Cables to pass",DATA.n);
  show("Grommets needed",Math.ceil(DATA.n/DATA.per));
  show("Per grommet","~"+DATA.per+" cables comfortable");
}else if(m==="mistake"){
  show("Mistake",DATA.bad);show("Instead",DATA.good);
}else if(m==="care"){
  show("Care","vacuum the brush inserts yearly");
  show("Check","seating after moving the desk");
}else if(m==="tray"){
  show("Grommets","vertical pass-through, invisible");
  show("Cable tray","horizontal runs under the desk");
  show("Together","the complete hidden path");
}else if(m==="workflow"){
  console.log("Grommet workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
